        // and also derive the other id from known types; we will check both possibilities separately

        // canonical ids
        bytes4 idIERC165 = type(IERC165).interfaceId;
        bytes4 idIAccessControl = type(IAccessControl).interfaceId;

        // We want a single assertion that the reference satisfies for all inputs and the mutant breaks for some.
        // Construct a boolean that is true exactly when interfaceId equals either canonical id,
        // and then read c.supportsInterface(interfaceId) (non-reverting) and assert that
