            // so make a noop by asserting ok || !ok (always true) but that would be constant; instead avoid asserting here.
            // However the test must contain exactly one assertTrue: so we structure differently: force a single assertion
            // by mapping the condition into a single boolean that must be true for all inputs.
        }
    }
}

