        // hasRole(bytes32,address) => bytes4(keccak256("hasRole(bytes32,address)"))
        // getRoleAdmin(bytes32) => bytes4(keccak256("getRoleAdmin(bytes32)"))
        // grantRole(bytes32,address) => bytes4(keccak256("grantRole(bytes32,address)"))
